/* Captcha bridge, copied verbatim from the working /contact-us page (Brevo expects reCAPTCHA; we run Turnstile).
   Guarded, so a page that already carries it is untouched. */
(function () {
  if (window.handleCaptchaResponse) return;
  function ensureAlias() { if (window.turnstile) window.grecaptcha = window.turnstile; }
  var tries = 0;
  var iv = setInterval(function () {
    if (window.turnstile) { ensureAlias(); clearInterval(iv); }
    else if (++tries > 50) clearInterval(iv);
  }, 100);
  document.addEventListener('submit', function (e) {
    if (e.target && e.target.id === 'sib-form') ensureAlias();
  }, true);
  window.handleCaptchaResponse = function (token) {
    ensureAlias();
    var ta = document.getElementById('g-recaptcha-response');
    if (ta && token) ta.value = token;
    var el = document.getElementById('sib-captcha');
    if (el) el.dispatchEvent(new Event('captchaChange'));
  };
})();


(function () {
  function run() {
    if (window.gtmEnqReady) return; /* never wire the form twice if the script is included twice */
    window.gtmEnqReady = true;
/* Capella enquiry: which hotel(s), where the visitor came from, and the GA4 lead on success. */
(function () {
  var card = document.querySelector('.gtm-enq');
  if (!card) return;
  var mode = card.getAttribute('data-enq-mode');
  var form = card.querySelector('#sib-form');
  if (!form) return;
  var interest = form.querySelector('input[name="INTEREST_LAST"]');
  var source = form.querySelector('input[name="ENQUIRY_SOURCE"]');
  var FALLBACK = [['capella-bangkok', 'Capella Bangkok'], ['capella-singapore', 'Capella Singapore'],
    ['capella-taipei', 'Capella Taipei'], ['patina-maldives', 'Patina Maldives'],
    ['patina-osaka', 'Patina Osaka'], ['capella-kyoto', 'Capella Kyoto']];

  /* ---- which hotel(s) ---- */
  var pageSlug = (window.location.pathname.match(/\/stay\/([a-z0-9-]+)/) || [])[1] || '';
  function hotelsOnPage() {
    var seen = {}, out = [];
    var links = document.querySelectorAll('a[href*="/stay/"]');
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      if (card.contains(a)) continue;
      var m = (a.getAttribute('href') || '').match(/\/stay\/([a-z0-9-]+)/);
      if (!m || seen[m[1]]) continue;
      var item = a.closest('.w-dyn-item');
      var h = item ? item.querySelector('h1, h2, h3') : null;
      var name = h ? h.textContent.trim() : '';
      if (!name) continue;
      seen[m[1]] = true;
      out.push([m[1], name]);
    }
    return out.length ? out : FALLBACK;
  }

  var boxes = [];
  function chosen() {
    var s = [];
    for (var i = 0; i < boxes.length; i++) if (boxes[i].checked) s.push(boxes[i].value);
    return s;
  }
  var errorEl = card.querySelector('[data-enq="hotel-error"]');
  function syncInterest() {
    interest.value = mode === 'hub' ? chosen().join(', ') : pageSlug;
    if (errorEl && chosen().length) errorEl.textContent = '';
  }

  if (mode === 'hub') {
    var grid = card.querySelector('[data-enq="hotel-grid"]');
    hotelsOnPage().forEach(function (h) {
      var label = document.createElement('label');
      label.className = 'gtm-enq__hotel';
      var input = document.createElement('input');
      input.type = 'checkbox';
      input.value = h[0];
      var tick = document.createElement('span');
      tick.className = 'gtm-enq__tick';
      tick.setAttribute('aria-hidden', 'true');
      var name = document.createElement('span');
      name.textContent = h[1];
      label.appendChild(input); label.appendChild(tick); label.appendChild(name);
      input.addEventListener('change', function () { label.classList.toggle('is-on', input.checked); syncInterest(); });
      grid.appendChild(label);
      boxes.push(input);
    });
  } else {
    var h1 = document.querySelector('h1');
    var hotelName = h1 ? h1.textContent.trim() : '';
    var sub = card.querySelector('[data-enq="sub"]');
    if (sub && hotelName) sub.textContent = 'Leave your details and we will book ' + hotelName + ' for you, privileges included.';
  }
  syncInterest();

  /* ---- where they came from: the booking embeds already remember it for the tab (gtm_inbound) ---- */
  function inbound() {
    var v = null;
    try { v = JSON.parse(window.sessionStorage.getItem('gtm_inbound') || 'null'); } catch (e) { v = null; }
    if (!v || !v.utm_source) {
      var q = {};
      window.location.search.slice(1).split('&').forEach(function (p) {
        var kv = p.split('=');
        if (/^utm_/.test(kv[0]) && kv[1]) { try { q[kv[0]] = decodeURIComponent(kv[1].replace(/\+/g, ' ')); } catch (e) {} }
      });
      if (q.utm_source) v = q;
    }
    if (!v || !v.utm_source) {
      var ref = '';
      try { ref = document.referrer ? new URL(document.referrer).hostname : ''; } catch (e) { ref = ''; }
      if (ref && !/(^|\.)globaltravelmoments\.com$|\.webflow\.io$/.test(ref)) v = { utm_source: ref.replace(/^www\./, ''), utm_medium: 'referral' };
    }
    var parts = (v && v.utm_source) ? [v.utm_source, v.utm_medium, v.utm_campaign, v.utm_content].filter(Boolean) : ['unknown'];
    return (parts.join(' / ') + ' \u00b7 ' + (mode === 'hub' ? 'hub' : 'hotel page')).slice(0, 190);
  }

  /* ---- hub: at least one hotel, checked before Brevo sees the submit (capture phase) ---- */
  function guard(e) {
    var isOurs = (e.type === 'submit' && e.target === form) ||
      (e.type === 'click' && e.target.closest && e.target.closest('.gtm-enq .sib-form-block__button'));
    if (!isOurs) return;
    syncInterest();
    source.value = inbound();
    if (mode === 'hub' && !chosen().length) {
      e.preventDefault();
      e.stopImmediatePropagation();
      if (errorEl) errorEl.textContent = 'Choose at least one hotel.';
      if (boxes[0]) boxes[0].focus();
    }
  }
  document.addEventListener('click', guard, true);
  document.addEventListener('submit', guard, true);

  /* ---- success: swap to the thank-you and record the lead once ---- */
  var done = false;
  var ok = card.querySelector('#success-message');
  function checkDone() {
    if (done || !ok) return;
    if (window.getComputedStyle(ok).display === 'none') return;
    done = true;
    card.classList.add('gtm-enq--done');
    var hotelId = document.querySelector('.gtm-shb [data-shb-field="id"]');
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
      event: 'capella_enquiry',
      enquiry_page: mode === 'hub' ? 'hub' : 'hotel',
      enquiry_hotels: interest.value,
      search_hotel_id: mode === 'hub' ? '' : (hotelId ? hotelId.textContent.trim() : '')
    });
  }
  if (ok && window.MutationObserver) new MutationObserver(checkDone).observe(ok, { attributes: true, attributeFilter: ['style', 'class'] });
})();

  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
  else run();
})();
